import type { Metadata, Viewport } from "next";
import Script from "next/script";
import "./globals.css";
import Footer from "../components/footer";
import BottomTabBar from "../components/BottomTabBar";
import { LangProvider } from "../contexts/LangContext";
import PageTransition from "../components/PageTransition";

export const metadata: Metadata = {
  title: "사주 프로젝트",
  description: "한양사주 — Gmarket Sans",
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  maximumScale: 5,
  userScalable: true,
};

export default async function RootLayout({
  children,
  params,
}: Readonly<{
  children: React.ReactNode;
  params?: Promise<Record<string, string | string[]>>;
}>) {
  if (params) await params;
  return (
    <html lang="ko">
      <head>
        <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=5, user-scalable=yes" />
        <meta name="theme-color" content="#F5F2EE" />
        <meta name="apple-mobile-web-app-capable" content="yes" />
        <meta name="apple-mobile-web-app-status-bar-style" content="default" />
      </head>
      <body className="antialiased" style={{ paddingBottom: 0, background: "var(--bg-base)" }}>
        <LangProvider>
        {/* Google Tag Manager (noscript) */}
        <noscript>
          <iframe
            src="https://www.googletagmanager.com/ns.html?id=GTM-KPH5HZM3"
            height="0"
            width="0"
            style={{ display: "none", visibility: "hidden" }}
            title="Google Tag Manager"
          />
        </noscript>
        <Script
          id="gtm"
          strategy="afterInteractive"
          dangerouslySetInnerHTML={{
            __html: `(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':
new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],
j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src=
'https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);
})(window,document,'script','dataLayer','GTM-KPH5HZM3');`,
          }}
        />
        <div className="flex flex-col min-h-screen relative" style={{ zIndex: 1 }}>
          <main className="flex-grow pb-0">
            <PageTransition>{children}</PageTransition>
          </main>

          {/* BottomTabBar — 나중에 사용할 수 있음 */}
          {/* <BottomTabBar /> */}

          {/* 푸터 중앙 정렬 래퍼 */}
          <div style={{ width: "100%", background: "inherit", paddingBottom: 16 }}>
            <div style={{ maxWidth: 390, margin: "0 auto", padding: "0 20px" }}>
              <Footer />
            </div>
          </div>

        </div>
        </LangProvider>
      </body>
    </html>
  );
}
